import{_ as a,o,c as s,a2 as t}from"./chunks/framework.BDCokyix.js";const b=JSON.parse('{"title":"Database & Migrations","description":"","frontmatter":{},"headers":[],"relativePath":"development/database.md","filePath":"development/database.md","lastUpdated":1780254295000}'),i={name:"development/database.md"};function r(d,e,n,l,c,p){return o(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="database-migrations" tabindex="-1">Database &amp; Migrations <a class="header-anchor" href="#database-migrations" aria-label="Permalink to &quot;Database &amp; Migrations&quot;">​</a></h1><p>Soma uses SQLx-backed storage for durable state such as join requests/decisions, memberships, and mailbox delivery.</p><h2 id="what-uses-a-database" tabindex="-1">What uses a database <a class="header-anchor" href="#what-uses-a-database" aria-label="Permalink to &quot;What uses a database&quot;">​</a></h2><ul><li><code>soma-daemon</code> (embedded in the Tauri <code>src-tauri</code> host via <code>desktop-daemon</code>, run in-process): SQLite file under the app&#39;s data dir — <code>~/Library/Application Support/Soma/</code> on macOS, <code>~/.local/share/soma/</code> on Linux (stage-specific <code>-dev</code> / <code>-staging</code> suffixes via <code>@soma/desktop-config</code>).</li><li><code>somad bot</code> (server peer): SQLx AnyPool with SQLite or Postgres (<code>SOMA_DATABASE_URL</code>, default <code>./botd.db</code>).</li></ul><p>Both apply migrations at startup and fail fast if migrations cannot be applied.</p><h2 id="migrations" tabindex="-1">Migrations <a class="header-anchor" href="#migrations" aria-label="Permalink to &quot;Migrations&quot;">​</a></h2><ul><li>Directory: <code>backend/crates/storage/migrations</code></li><li>Applied by: <ul><li><code>backend/crates/daemon/src/lib.rs</code> (the in-process daemon library) via <code>sqlx::migrate!(&quot;../storage/migrations&quot;)</code></li><li><code>backend/bins/somad/src/commands/bot/runtime.rs</code> via <code>sqlx::migrate!(&quot;../../crates/storage/migrations&quot;)</code></li></ul></li></ul><h2 id="access-layer-repositories" tabindex="-1">Access layer (repositories) <a class="header-anchor" href="#access-layer-repositories" aria-label="Permalink to &quot;Access layer (repositories)&quot;">​</a></h2><p>SQL is intentionally kept out of controllers/handlers. Repositories live in:</p><ul><li><code>backend/crates/storage/src/membership.rs</code></li><li><code>backend/crates/storage/src/issuer.rs</code></li><li><code>backend/crates/storage/src/mailbox.rs</code></li></ul><p>Repository wiring:</p><ul><li>Bootstrap: <code>backend/crates/storage/src/bootstrap.rs</code></li><li>Factory: <code>backend/crates/storage/src/lib.rs</code> (<code>RepositoryFactory</code>)</li></ul><h2 id="database-url-conventions" tabindex="-1">Database URL conventions <a class="header-anchor" href="#database-url-conventions" aria-label="Permalink to &quot;Database URL conventions&quot;">​</a></h2><ul><li>The code normalizes SQLite paths into <code>sqlite://...</code> URLs via <code>soma_core::db::normalize_sqlite_url</code> (<code>backend/crates/core/src/db.rs</code>).</li><li>For <code>somad bot</code>, <code>SOMA_DATABASE_URL</code> can be: <ul><li>a <code>postgres://...</code> URL, or</li><li>a SQLite URL/path (<code>sqlite:...</code> or a filesystem path).</li></ul></li></ul><h2 id="common-workflows" tabindex="-1">Common workflows <a class="header-anchor" href="#common-workflows" aria-label="Permalink to &quot;Common workflows&quot;">​</a></h2><h3 id="inspecting-the-desktop-daemon-db-sqlite" tabindex="-1">Inspecting the desktop daemon DB (SQLite) <a class="header-anchor" href="#inspecting-the-desktop-daemon-db-sqlite" aria-label="Permalink to &quot;Inspecting the desktop daemon DB (SQLite)&quot;">​</a></h3><p>The file lives under the desktop app&#39;s data directory — on macOS that is <code>~/Library/Application Support/Soma/</code>. On Linux it is <code>~/.local/share/soma/</code>.</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sqlite3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/Library/Application Support/Soma/soma.db&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.tables&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="running-against-a-fresh-db" tabindex="-1">Running against a fresh DB <a class="header-anchor" href="#running-against-a-fresh-db" aria-label="Permalink to &quot;Running against a fresh DB&quot;">​</a></h3><ul><li>Delete the DB file (e.g., the desktop DB under the app data dir, or <code>backend/botd.db</code> for the server bot) and restart the service.</li><li>Migrations will recreate the schema.</li></ul><h3 id="postgres-for-the-server-bot-deployments" tabindex="-1">Postgres for the server bot (deployments) <a class="header-anchor" href="#postgres-for-the-server-bot-deployments" aria-label="Permalink to &quot;Postgres for the server bot (deployments)&quot;">​</a></h3><ul><li>Set <code>SOMA_DATABASE_URL=postgres://...</code> for <code>somad bot</code>.</li><li>Ensure the database is reachable and credentials are correct; startup will fail if migrations cannot be applied.</li></ul>',22)])])}const m=a(i,[["render",r]]);export{b as __pageData,m as default};
